"""Exception hierarchy for microdb."""


class MicroDBError(Exception):
    """Base exception for all microdb errors."""


class LexError(MicroDBError):
    """Lexer error with zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class ParseError(MicroDBError):
    """Parser error with zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class SchemaError(MicroDBError):
    """Schema validation error."""


class TypeMismatchError(MicroDBError):
    """Type mismatch in operation."""


class UnknownColumnError(MicroDBError):
    """Reference to unknown column."""


class AmbiguousColumnError(MicroDBError):
    """Unqualified column reference that matches multiple tables."""


class UnknownTableError(MicroDBError):
    """Reference to unknown table."""


class UnknownFunctionError(MicroDBError):
    """Reference to unknown function."""


class ArityError(MicroDBError):
    """Wrong number of arguments to a function."""


class AggregateError(MicroDBError):
    """Aggregate used in wrong context."""


class GroupingError(MicroDBError):
    """Invalid SELECT item with GROUP BY."""

"""Value model, three-valued logic, comparison, arithmetic."""

from microdb.errors import TypeMismatchError


def type_of(v: object) -> str:
    """Return the type name of a value: INT, FLOAT, TEXT, BOOL, or NULL."""
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported type: {type(v).__name__}")


def is_numeric(v: object) -> bool:
    """True for int and float, False for bool and None."""
    return isinstance(v, (int, float)) and not isinstance(v, bool)


# ── Three-valued logic ──────────────────────────────────────────────────


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued logical AND."""
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued logical OR."""
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    """Three-valued logical NOT."""
    if a is None:
        return None
    return not a


# ── Comparison ──────────────────────────────────────────────────────────


def compare_eq(a: object, b: object) -> bool | None:
    """Compare a == b with NULL semantics and type checking.

    Returns UNKNOWN (None) if either operand is NULL.
    """
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return _py_eq(a, b)


def compare_lt(a: object, b: object) -> bool | None:
    """Compare a < b with NULL semantics and type checking.

    Returns UNKNOWN (None) if either operand is NULL.
    """
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return _py_lt(a, b)


def _check_comparable(a: object, b: object) -> None:
    """Raise TypeMismatchError if a and b cannot be compared."""
    ta = type_of(a)
    tb = type_of(b)
    if ta == tb:
        return
    # INT and FLOAT are comparable with each other
    if {ta, tb} <= {"INT", "FLOAT"}:
        return
    raise TypeMismatchError(
        f"cannot compare {ta} with {tb}"
    )


def _py_eq(a: object, b: object) -> bool:
    """Python-level equality, handling numeric type promotion."""
    ta = type_of(a)
    tb = type_of(b)
    if ta == "INT" and tb == "FLOAT":
        return a == b  # int == float works in Python
    if ta == "FLOAT" and tb == "INT":
        return a == b
    return a == b


def _py_lt(a: object, b: object) -> bool:
    """Python-level less-than, handling numeric type promotion."""
    ta = type_of(a)
    tb = type_of(b)
    if ta == "INT" and tb == "FLOAT":
        return a < b
    if ta == "FLOAT" and tb == "INT":
        return a < b
    return a < b


# ── Arithmetic ──────────────────────────────────────────────────────────


def arith(op: str, a: object, b: object) -> object:
    """Perform arithmetic operation. op in '+-*/%'.

    Returns NULL on NULL input or division by zero.
    """
    if a is None or b is None:
        return None

    ta = type_of(a)
    tb = type_of(b)

    if not is_numeric(a) or not is_numeric(b):
        raise TypeMismatchError(
            f"arithmetic {op} requires numeric operands, got {ta}, {tb}"
        )

    if op == "+":
        if ta == "FLOAT" or tb == "FLOAT":
            return float(a) + float(b)
        return a + b
    elif op == "-":
        if ta == "FLOAT" or tb == "FLOAT":
            return float(a) - float(b)
        return a - b
    elif op == "*":
        if ta == "FLOAT" or tb == "FLOAT":
            return float(a) * float(b)
        return a * b
    elif op == "/":
        b_val = float(b)
        if b_val == 0.0:
            return None
        return float(a) / b_val
    elif op == "%":
        if ta != "INT" or tb != "INT":
            raise TypeMismatchError(
                f"modulo requires INT operands, got {ta}, {tb}"
            )
        if b == 0:
            return None
        return a % b
    else:
        raise ValueError(f"unknown arithmetic operator: {op}")


def negate(a: object) -> object:
    """Negate a numeric value. NULL propagates."""
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(
            f"negate requires numeric operand, got {type_of(a)}"
        )
    return -a

"""Column and Table classes."""

import dataclasses
from typing import Any

from microdb.errors import SchemaError
from microdb.value import type_of


@dataclasses.dataclass(frozen=True)
class Column:
    """A column definition."""

    name: str
    type: str  # "INT" | "FLOAT" | "TEXT" | "BOOL"

    def __post_init__(self) -> None:
        if self.type not in ("INT", "FLOAT", "TEXT", "BOOL"):
            raise SchemaError(f"invalid column type: {self.type}")


_VALID_TYPES = frozenset({"INT", "FLOAT", "TEXT", "BOOL"})


class Table:
    """An in-memory table with validated rows."""

    __slots__ = ("_name", "_columns", "_rows")

    def __init__(
        self, name: str, columns: list[Column], rows: list[list[object]]
    ) -> None:
        if not columns:
            raise SchemaError("table must have at least one column")
        if len(columns) != len({c.name for c in columns}):
            raise SchemaError("duplicate column name")
        for c in columns:
            if c.type not in _VALID_TYPES:
                raise SchemaError(f"invalid column type: {c.type}")
        col_count = len(columns)
        for i, row in enumerate(rows):
            if len(row) != col_count:
                raise SchemaError(
                    f"row {i} has {len(row)} values, expected {col_count}"
                )
            for j, cell in enumerate(row):
                if cell is None:
                    continue
                expected = columns[j].type
                actual = type_of(cell)
                # FLOAT columns accept int and convert
                if expected == "FLOAT" and actual == "INT":
                    row[j] = float(cell)
                elif actual != expected:
                    raise SchemaError(
                        f"row {i}, column '{columns[j].name}': "
                        f"expected {expected}, got {actual}"
                    )
        self._name = name
        self._columns = list(columns)
        self._rows = [list(row) for row in rows]

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return list(self._columns)

    @property
    def rows(self) -> list[list[object]]:
        return [list(r) for r in self._rows]

    def column_index(self, name: str) -> int:
        """Return the index of a column by name. Raises SchemaError if unknown."""
        for i, c in enumerate(self._columns):
            if c.name == name:
                return i
        raise SchemaError(f"unknown column: {name}")

"""Recursive-descent parser for the microdb query language.

Produces a Query dataclass with expression AST nodes.
"""

from dataclasses import dataclass, field
from typing import Any

from microdb.errors import ParseError
from microdb.lexer import (
    Token,
    tokenize,
    INT,
    FLOAT,
    TEXT,
    IDENTIFIER,
    KEYWORD,
    OPERATOR,
    EOF,
)


# ── Expression AST nodes ───────────────────────────────────────────────


@dataclass
class Literal:
    """A literal value (int, float, str, bool, None)."""
    value: object


@dataclass
class ColumnRef:
    """An unqualified column reference."""
    name: str


@dataclass
class QualifiedColumnRef:
    """A qualified column reference (table.column)."""
    table: str
    name: str


@dataclass
class FunctionCall:
    """A function or aggregate call."""
    name: str
    args: list[Any]


@dataclass
class BinaryOp:
    """A binary operation."""
    op: str
    left: Any
    right: Any


@dataclass
class UnaryOp:
    """A unary operation (NOT or negation)."""
    op: str
    operand: Any


@dataclass
class IsNull:
    """IS NULL or IS NOT NULL predicate."""
    operand: Any
    negated: bool = False


# ── Select items ───────────────────────────────────────────────────────


@dataclass
class Star:
    """SELECT *"""
    pass


@dataclass
class StarTable:
    """SELECT table_name.*"""
    table: str


@dataclass
class SelectExpr:
    """SELECT expression [AS alias]"""
    expr: Any
    alias: str | None = None


# ── Join ───────────────────────────────────────────────────────────────


@dataclass
class Join:
    """A JOIN clause."""
    type: str  # "INNER" or "LEFT"
    table: str
    on: Any


# ── ORDER BY ───────────────────────────────────────────────────────────


@dataclass
class OrderBy:
    """A single ORDER BY item."""
    expr: Any
    ascending: bool = True


# ── Query ──────────────────────────────────────────────────────────────


@dataclass
class Query:
    """A fully parsed query."""
    distinct: bool = False
    select_items: list[Any] = field(default_factory=list)
    from_table: str = ""
    join: Join | None = None
    where: Any = None
    group_by: list[Any] = field(default_factory=list)
    having: Any = None
    order_by: list[OrderBy] = field(default_factory=list)
    limit: int | None = None
    offset: int | None = None


# ── Parser ─────────────────────────────────────────────────────────────


class Parser:
    """Recursive-descent parser."""

    __slots__ = ("tokens", "pos")

    def __init__(self, tokens: list[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    # ── helpers ─────────────────────────────────────────────────────

    def _peek(self) -> Token:
        return self.tokens[self.pos]

    def _advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _expect(self, kind: str, value: Any = None) -> Token:
        tok = self._peek()
        if value is not None:
            if tok.type != kind or tok.value != value:
                raise ParseError(
                    f"expected {value!r}, got {tok.value!r}",
                    tok.offset,
                )
        elif tok.type != kind:
            raise ParseError(
                f"expected {kind}, got {tok.type} ({tok.value!r})",
                tok.offset,
            )
        return self._advance()

    def _match(self, kind: str, value: Any = None) -> bool:
        tok = self._peek()
        if value is not None:
            if tok.type == kind and tok.value == value:
                self._advance()
                return True
            return False
        if tok.type == kind:
            self._advance()
            return True
        return False

    # ── main entry ──────────────────────────────────────────────────

    def parse(self) -> Query:
        """Parse a full SELECT statement."""
        q = Query()
        self._parse_select(q)
        self._parse_from(q)
        self._parse_join(q)
        self._parse_where(q)
        self._parse_group_by(q)
        self._parse_having(q)
        self._parse_order_by(q)
        self._parse_limit(q)
        self._parse_offset(q)
        self._expect(EOF)
        return q

    def _parse_select(self, q: Query) -> None:
        self._expect(KEYWORD, "SELECT")
        if self._match(KEYWORD, "DISTINCT"):
            q.distinct = True

        items: list[Any] = []
        while True:
            items.append(self._parse_select_item())
            if not self._match(OPERATOR, ","):
                break
        q.select_items = items

    def _parse_select_item(self) -> Any:
        """Parse a single select item: * | ident.* | expr [AS alias]."""
        tok = self._peek()

        if tok.type == OPERATOR and tok.value == "*":
            self._advance()
            return Star()

        if tok.type == IDENTIFIER:
            # Check for ident.* or ident (function call)
            name = tok.value
            save = self.pos
            self._advance()
            if self._match(OPERATOR, "."):
                if self._match(OPERATOR, "*"):
                    return StarTable(name)
                # Qualified column reference: t.c
                # Rewind: we need to parse as expression
                self.pos = save
                expr = self._parse_or_expr()
                if self._match(KEYWORD, "AS"):
                    alias = self._expect(IDENTIFIER).value
                    return SelectExpr(expr, alias)
                return SelectExpr(expr)
            # Rewind and parse as expression
            self.pos = save

        expr = self._parse_or_expr()
        if self._match(KEYWORD, "AS"):
            alias = self._expect(IDENTIFIER).value
            return SelectExpr(expr, alias)
        return SelectExpr(expr)

    # ── FROM ────────────────────────────────────────────────────────

    def _parse_from(self, q: Query) -> None:
        self._expect(KEYWORD, "FROM")
        q.from_table = self._expect(IDENTIFIER).value

    # ── JOIN ────────────────────────────────────────────────────────

    def _parse_join(self, q: Query) -> None:
        if not self._match(KEYWORD, "INNER") and not self._match(KEYWORD, "LEFT"):
            if self._peek().type == KEYWORD and self._peek().value == "JOIN":
                # Bare JOIN defaults to INNER
                pass
            else:
                return

        join_type = "INNER"
        if self.tokens[self.pos - 1].value == "LEFT":
            join_type = "LEFT"

        self._expect(KEYWORD, "JOIN")
        table = self._expect(IDENTIFIER).value
        self._expect(KEYWORD, "ON")
        on_expr = self._parse_or_expr()
        q.join = Join(type=join_type, table=table, on=on_expr)

    # ── WHERE ───────────────────────────────────────────────────────

    def _parse_where(self, q: Query) -> None:
        if not self._match(KEYWORD, "WHERE"):
            return
        q.where = self._parse_or_expr()

    # ── GROUP BY ────────────────────────────────────────────────────

    def _parse_group_by(self, q: Query) -> None:
        if not self._match(KEYWORD, "GROUP"):
            return
        self._expect(KEYWORD, "BY")
        exprs: list[Any] = []
        while True:
            exprs.append(self._parse_or_expr())
            if not self._match(OPERATOR, ","):
                break
        q.group_by = exprs

    # ── HAVING ──────────────────────────────────────────────────────

    def _parse_having(self, q: Query) -> None:
        if not self._match(KEYWORD, "HAVING"):
            return
        q.having = self._parse_or_expr()

    # ── ORDER BY ────────────────────────────────────────────────────

    def _parse_order_by(self, q: Query) -> None:
        if not self._match(KEYWORD, "ORDER"):
            return
        self._expect(KEYWORD, "BY")
        items: list[OrderBy] = []
        while True:
            expr = self._parse_or_expr()
            asc = True
            if self._match(KEYWORD, "ASC"):
                asc = True
            elif self._match(KEYWORD, "DESC"):
                asc = False
            items.append(OrderBy(expr, asc))
            if not self._match(OPERATOR, ","):
                break
        q.order_by = items

    # ── LIMIT / OFFSET ──────────────────────────────────────────────

    def _parse_limit(self, q: Query) -> None:
        if not self._match(KEYWORD, "LIMIT"):
            return
        tok = self._expect(INT)
        q.limit = int(tok.value)

    def _parse_offset(self, q: Query) -> None:
        if not self._match(KEYWORD, "OFFSET"):
            return
        tok = self._expect(INT)
        q.offset = int(tok.value)

    # ── Expression parsing ──────────────────────────────────────────
    #
    #  or_expr        := and_expr (OR and_expr)*
    #  and_expr       := not_expr (AND not_expr)*
    #  not_expr       := NOT not_expr | predicate
    #  predicate      := additive (cmp_op additive | IS [NOT] NULL)?
    #  additive       := multiplicative ((+ | -) multiplicative)*
    #  multiplicative := unary ((* | / | %) unary)*
    #  unary          := - unary | primary
    #  primary        := INT | FLOAT | TEXT | TRUE | FALSE | NULL
    #                   | ident | ident . ident
    #                   | ident ( arg_list? )
    #                   | ( or_expr )

    def _parse_or_expr(self) -> Any:
        left = self._parse_and_expr()
        while self._match(KEYWORD, "OR"):
            right = self._parse_and_expr()
            left = BinaryOp("OR", left, right)
        return left

    def _parse_and_expr(self) -> Any:
        left = self._parse_not_expr()
        while self._match(KEYWORD, "AND"):
            right = self._parse_not_expr()
            left = BinaryOp("AND", left, right)
        return left

    def _parse_not_expr(self) -> Any:
        if self._match(KEYWORD, "NOT"):
            operand = self._parse_not_expr()
            return UnaryOp("NOT", operand)
        return self._parse_predicate()

    def _parse_predicate(self) -> Any:
        left = self._parse_additive()

        tok = self._peek()
        if tok.type == OPERATOR and tok.value in ("=", "<>", "<", "<=", ">", ">="):
            op = self._advance().value
            right = self._parse_additive()
            return BinaryOp(op, left, right)

        if tok.type == KEYWORD and tok.value == "IS":
            self._advance()
            negated = self._match(KEYWORD, "NOT")
            self._expect(KEYWORD, "NULL")
            return IsNull(left, negated)

        return left  # no comparison or IS NULL

    def _parse_additive(self) -> Any:
        left = self._parse_multiplicative()
        while True:
            tok = self._peek()
            if tok.type == OPERATOR and tok.value in ("+", "-"):
                op = self._advance().value
                right = self._parse_multiplicative()
                left = BinaryOp(op, left, right)
            else:
                break
        return left

    def _parse_multiplicative(self) -> Any:
        left = self._parse_unary()
        while True:
            tok = self._peek()
            if tok.type == OPERATOR and tok.value in ("*", "/", "%"):
                op = self._advance().value
                right = self._parse_unary()
                left = BinaryOp(op, left, right)
            else:
                break
        return left

    def _parse_unary(self) -> Any:
        if self._match(OPERATOR, "-"):
            operand = self._parse_unary()
            return UnaryOp("-", operand)
        return self._parse_primary()

    def _parse_primary(self) -> Any:
        tok = self._peek()

        if tok.type in (INT, FLOAT, TEXT):
            self._advance()
            return Literal(tok.value)

        if tok.type == IDENTIFIER:
            name = tok.value
            self._advance()
            # Check for function call
            if self._peek().type == OPERATOR and self._peek().value == "(":
                return self._parse_function_call(name)
            # Check for qualified reference
            if self._match(OPERATOR, "."):
                col = self._expect(IDENTIFIER).value
                return QualifiedColumnRef(name, col)
            return ColumnRef(name)

        if tok.type == OPERATOR and tok.value == "(":
            self._advance()
            expr = self._parse_or_expr()
            self._expect(OPERATOR, ")")
            return expr

        raise ParseError(
            f"unexpected token: {tok.type} ({tok.value!r})",
            tok.offset,
        )

    def _parse_function_call(self, name: str) -> FunctionCall:
        """Parse ( arg_list? ).  The opening '(' has not been consumed."""
        args: list[Any] = []
        self._advance()  # consume '('
        if not (self._peek().type == OPERATOR and self._peek().value == ")"):
            # Check for star arg (count(*))
            if (
                self._peek().type == OPERATOR
                and self._peek().value == "*"
                and name.upper() == "COUNT"
            ):
                self._advance()  # consume *
                args.append(Star())
            else:
                while True:
                    args.append(self._parse_or_expr())
                    if not self._match(OPERATOR, ","):
                        break
        self._expect(OPERATOR, ")")
        return FunctionCall(name, args)


# ── Convenience wrapper ────────────────────────────────────────────────


def parse(source: str) -> Query:
    """Tokenize and parse a query string into a Query object."""
    tokens = tokenize(source)
    return Parser(tokens).parse()

"""Expression evaluation engine.

Evaluates expression AST nodes in the context of a data row.
"""

from microdb.parser import (
    Literal,
    ColumnRef,
    QualifiedColumnRef,
    FunctionCall,
    BinaryOp,
    UnaryOp,
    IsNull,
    Star,
)
from microdb.value import (
    type_of,
    and_,
    or_,
    not_,
    compare_eq,
    compare_lt,
    arith,
    negate,
)
from microdb.errors import (
    TypeMismatchError,
    UnknownColumnError,
    AmbiguousColumnError,
    UnknownTableError,
    UnknownFunctionError,
    ArityError,
    AggregateError,
    MicroDBError,
)


class EvalContext:
    """Evaluation context holding row data and metadata."""

    __slots__ = (
        "row",
        "col_names",
        "table_col_map",
        "table_names",
        "tables",
    )

    def __init__(
        self,
        row: list[object] | None = None,
        col_names: list[str] | None = None,
        table_col_map: dict[str, dict[str, int]] | None = None,
        tables: dict[str, object] | None = None,
    ) -> None:
        self.row = row if row is not None else []
        self.col_names = col_names if col_names is not None else []
        # table -> {column_name -> index}
        self.table_col_map = (
            table_col_map if table_col_map is not None else {}
        )
        self.table_names = set(self.table_col_map.keys())
        self.tables = tables if tables is not None else {}

    def with_row(self, row: list[object]) -> "EvalContext":
        """Return a new context with a different row but same schema."""
        return EvalContext(
            row=row,
            col_names=self.col_names,
            table_col_map=self.table_col_map,
            tables=self.tables,
        )


def evaluate(expr: object, ctx: EvalContext) -> object:
    """Evaluate an expression AST in the given context."""
    if isinstance(expr, Literal):
        return expr.value

    if isinstance(expr, ColumnRef):
        return _resolve_column(expr.name, ctx)

    if isinstance(expr, QualifiedColumnRef):
        return _resolve_qualified(expr.table, expr.name, ctx)

    if isinstance(expr, FunctionCall):
        return _eval_function(expr, ctx)

    if isinstance(expr, BinaryOp):
        return _eval_binary(expr.op, expr.left, expr.right, ctx)

    if isinstance(expr, UnaryOp):
        val = evaluate(expr.operand, ctx)
        if expr.op == "NOT":
            if not isinstance(val, (bool, type(None))):
                raise TypeMismatchError(
                    f"NOT requires boolean, got {type_of(val)}"
                )
            return not_(val)
        if expr.op == "-":
            return negate(val)
        raise ValueError(f"unknown unary op: {expr.op}")

    if isinstance(expr, IsNull):
        val = evaluate(expr.operand, ctx)
        if expr.negated:
            return val is not None
        return val is None

    if isinstance(expr, Star):
        # count(*) - represented as Star
        return expr

    raise ValueError(f"unknown expression type: {type(expr).__name__}")


def _resolve_column(name: str, ctx: EvalContext) -> object:
    """Resolve an unqualified column reference."""
    candidates: list[int] = []
    for tbl, cmap in ctx.table_col_map.items():
        if name in cmap:
            candidates.append(cmap[name])

    if len(candidates) == 0:
        raise UnknownColumnError(f"unknown column: {name}")
    if len(candidates) > 1:
        raise AmbiguousColumnError(
            f"column {name!r} is ambiguous"
        )
    return ctx.row[candidates[0]]


def _resolve_qualified(table: str, name: str, ctx: EvalContext) -> object:
    """Resolve a qualified column reference (table.column)."""
    if table not in ctx.table_col_map:
        raise UnknownTableError(f"unknown table: {table}")
    cmap = ctx.table_col_map[table]
    if name not in cmap:
        raise UnknownColumnError(
            f"column {name!r} not in table {table!r}"
        )
    return ctx.row[cmap[name]]


def _eval_function(call: FunctionCall, ctx: EvalContext) -> object:
    """Evaluate a scalar function call."""
    fname = call.name.upper()
    args = call.args

    if fname == "CONCAT":
        if len(args) < 2:
            raise ArityError(
                f"concat requires at least 2 arguments, got {len(args)}"
            )
        evaled = [evaluate(a, ctx) for a in args]
        for v in evaled:
            if v is None:
                return None
            if type_of(v) != "TEXT":
                raise TypeMismatchError(
                    f"concat requires TEXT, got {type_of(v)}"
                )
        return "".join(evaled)

    if fname == "UPPER":
        if len(args) != 1:
            raise ArityError(f"upper requires 1 argument, got {len(args)}")
        val = evaluate(args[0], ctx)
        if val is None:
            return None
        if type_of(val) != "TEXT":
            raise TypeMismatchError(
                f"upper requires TEXT, got {type_of(val)}"
            )
        return val.upper()

    if fname == "LOWER":
        if len(args) != 1:
            raise ArityError(f"lower requires 1 argument, got {len(args)}")
        val = evaluate(args[0], ctx)
        if val is None:
            return None
        if type_of(val) != "TEXT":
            raise TypeMismatchError(
                f"lower requires TEXT, got {type_of(val)}"
            )
        return val.lower()

    if fname == "LENGTH":
        if len(args) != 1:
            raise ArityError(f"length requires 1 argument, got {len(args)}")
        val = evaluate(args[0], ctx)
        if val is None:
            return None
        if type_of(val) != "TEXT":
            raise TypeMismatchError(
                f"length requires TEXT, got {type_of(val)}"
            )
        return len(val)

    if fname == "ABS":
        if len(args) != 1:
            raise ArityError(f"abs requires 1 argument, got {len(args)}")
        val = evaluate(args[0], ctx)
        if val is None:
            return None
        if type_of(val) not in ("INT", "FLOAT"):
            raise TypeMismatchError(
                f"abs requires numeric, got {type_of(val)}"
            )
        if isinstance(val, int):
            return abs(val)
        return abs(val)

    if fname == "COALESCE":
        if len(args) < 1:
            raise ArityError(
                f"coalesce requires at least 1 argument, got {len(args)}"
            )
        for a in args:
            v = evaluate(a, ctx)
            if v is not None:
                return v
        return None

    raise UnknownFunctionError(f"unknown function: {call.name}")


def _eval_binary(
    op: str, left: object, right: object, ctx: EvalContext
) -> object:
    """Evaluate a binary operation."""
    # Logical operators short-circuit for three-valued logic
    if op == "AND":
        lv = evaluate(left, ctx)
        if not isinstance(lv, (bool, type(None))):
            raise TypeMismatchError(
                f"AND requires boolean, got {type_of(lv)}"
            )
        if lv is False:
            return False
        rv = evaluate(right, ctx)
        if not isinstance(rv, (bool, type(None))):
            raise TypeMismatchError(
                f"AND requires boolean, got {type_of(rv)}"
            )
        return and_(lv, rv)

    if op == "OR":
        lv = evaluate(left, ctx)
        if not isinstance(lv, (bool, type(None))):
            raise TypeMismatchError(
                f"OR requires boolean, got {type_of(lv)}"
            )
        if lv is True:
            return True
        rv = evaluate(right, ctx)
        if not isinstance(rv, (bool, type(None))):
            raise TypeMismatchError(
                f"OR requires boolean, got {type_of(rv)}"
            )
        return or_(lv, rv)

    # Comparison operators
    if op in ("=", "<>", "<", "<=", ">", ">="):
        lv = evaluate(left, ctx)
        rv = evaluate(right, ctx)
        result = _compare(op, lv, rv)
        return result

    # Arithmetic operators
    if op in ("+", "-", "*", "/", "%"):
        lv = evaluate(left, ctx)
        rv = evaluate(right, ctx)
        return arith(op, lv, rv)

    raise ValueError(f"unknown binary op: {op}")


def _compare(op: str, a: object, b: object) -> bool | None:
    """Compare two values with the given operator."""
    if op == "=":
        return compare_eq(a, b)
    if op == "<>":
        eq = compare_eq(a, b)
        if eq is None:
            return None
        return not eq
    if op == "<":
        return compare_lt(a, b)
    if op == "<=":
        lt = compare_lt(a, b)
        if lt is True:
            return True
        eq = compare_eq(a, b)
        if eq is True:
            return True
        if lt is None or eq is None:
            return None
        return False
    if op == ">":
        lt = compare_lt(a, b)
        if lt is None:
            return None
        return not (lt or compare_eq(a, b))
    if op == ">=":
        lt = compare_lt(a, b)
        if lt is None:
            return None
        return not lt
    raise ValueError(f"unknown comparison: {op}")


def has_aggregate(expr: object) -> bool:
    """Return True if the expression contains any aggregate function call."""
    if isinstance(expr, FunctionCall):
        if expr.name.upper() in ("COUNT", "SUM", "AVG", "MIN", "MAX"):
            return True
        # Check args for nested aggregates (which should raise error)
        return any(has_aggregate(a) for a in expr.args)
    if isinstance(expr, BinaryOp):
        return has_aggregate(expr.left) or has_aggregate(expr.right)
    if isinstance(expr, UnaryOp):
        return has_aggregate(expr.operand)
    if isinstance(expr, IsNull):
        return has_aggregate(expr.operand)
    return False


def contains_aggregate(expr: object) -> bool:
    """Return True and also detect nested aggregates (error case)."""
    found = [False]

    def _walk(node: object) -> None:
        if isinstance(node, FunctionCall):
            if node.name.upper() in ("COUNT", "SUM", "AVG", "MIN", "MAX"):
                if found[0]:
                    # Nested aggregate
                    raise AggregateError(
                        "aggregates may not be nested"
                    )
                found[0] = True
            for a in node.args:
                _walk(a)
        elif isinstance(node, BinaryOp):
            _walk(node.left)
            _walk(node.right)
        elif isinstance(node, UnaryOp):
            _walk(node.operand)
        elif isinstance(node, IsNull):
            _walk(node.operand)

    _walk(expr)
    return found[0]


def collect_aggregates(expr: object) -> list[FunctionCall]:
    """Return a list of aggregate function calls found in the expression."""
    aggrs: list[FunctionCall] = []

    def _walk(node: object) -> None:
        if isinstance(node, FunctionCall):
            if node.name.upper() in ("COUNT", "SUM", "AVG", "MIN", "MAX"):
                aggrs.append(node)
            for a in node.args:
                _walk(a)
        elif isinstance(node, BinaryOp):
            _walk(node.left)
            _walk(node.right)
        elif isinstance(node, UnaryOp):
            _walk(node.operand)
        elif isinstance(node, IsNull):
            _walk(node.operand)

    _walk(expr)
    return aggrs

"""Aggregate function implementations."""

from microdb.value import type_of, is_numeric
from microdb.errors import TypeMismatchError, ArityError
from microdb.parser import Star, FunctionCall


def eval_aggregate(
    call: FunctionCall,
    rows: list[list[object]],
    eval_row_fn: object,
) -> object:
    """Evaluate an aggregate function over a list of rows.

    eval_row_fn is a callable(expr, row) -> value that evaluates
    an expression against a single row.
    """
    name = call.name.upper()
    args = call.args

    if name == "COUNT":
        if len(args) != 1:
            raise ArityError(
                f"count requires 1 argument, got {len(args)}"
            )
        if isinstance(args[0], Star):
            return len(rows)
        # count(expr) - count non-NULL values
        count = 0
        for row in rows:
            val = eval_row_fn(args[0], row)
            if val is not None:
                count += 1
        return count

    if name == "SUM":
        if len(args) != 1:
            raise ArityError(f"sum requires 1 argument, got {len(args)}")
        return _numeric_agg(name, args[0], rows, eval_row_fn, "sum")

    if name == "AVG":
        if len(args) != 1:
            raise ArityError(f"avg requires 1 argument, got {len(args)}")
        return _numeric_agg(name, args[0], rows, eval_row_fn, "avg")

    if name == "MIN":
        if len(args) != 1:
            raise ArityError(f"min requires 1 argument, got {len(args)}")
        return _ordered_agg(name, args[0], rows, eval_row_fn, "min")

    if name == "MAX":
        if len(args) != 1:
            raise ArityError(f"max requires 1 argument, got {len(args)}")
        return _ordered_agg(name, args[0], rows, eval_row_fn, "max")

    raise ValueError(f"unknown aggregate: {call.name}")


def _numeric_agg(
    name: str,
    expr: object,
    rows: list[list[object]],
    eval_row_fn: object,
    op: str,
) -> object:
    """Evaluate SUM or AVG over non-NULL values."""
    values: list[object] = []
    for row in rows:
        val = eval_row_fn(expr, row)
        if val is None:
            continue
        t = type_of(val)
        if not is_numeric(val):
            raise TypeMismatchError(
                f"{name} requires numeric, got {t}"
            )
        values.append(val)

    if not values:
        return None  # sum/avg of nothing is NULL

    if op == "sum":
        # sum: INT if all INT, FLOAT otherwise
        all_int = all(isinstance(v, int) for v in values)
        result = sum(values)
        if all_int:
            return result  # int
        return float(result)

    # avg: always FLOAT
    total = sum(float(v) for v in values)
    return total / len(values)


def _ordered_agg(
    name: str,
    expr: object,
    rows: list[list[object]],
    eval_row_fn: object,
    op: str,
) -> object:
    """Evaluate MIN or MAX over non-NULL values."""
    from microdb.value import compare_lt

    found: object = None
    found_type: str | None = None

    for row in rows:
        val = eval_row_fn(expr, row)
        if val is None:
            continue
        vt = type_of(val)
        if found is None:
            found = val
            found_type = vt
        else:
            # Type check: all must be same type (or INT/FLOAT mix)
            if vt != found_type:
                if {vt, found_type} <= {"INT", "FLOAT"}:
                    # Promote to FLOAT for mixing types
                    found_v = float(found) if isinstance(found, int) else found
                    val_v = float(val) if isinstance(val, int) else val
                    if op == "min":
                        found = found_v if found_v < val_v else val_v
                    else:
                        found = found_v if found_v > val_v else val_v
                    found_type = "FLOAT"
                else:
                    raise TypeMismatchError(
                        f"{name} type mismatch: {found_type} vs {vt}"
                    )
            else:
                if op == "min":
                    if compare_lt(val, found) is True:
                        found = val
                else:
                    if compare_lt(found, val) is True:
                        found = val

    return found

"""Query planner: converts a Query into an ordered list of Plan stages."""

from dataclasses import dataclass, field
from typing import Any

from microdb.parser import Query


# ── Plan stages ────────────────────────────────────────────────────────


@dataclass
class ScanStage:
    """Read all rows from a table."""
    table: str


@dataclass
class JoinStage:
    """Perform a join with another table."""
    join_type: str  # "INNER" or "LEFT"
    table: str
    on: Any


@dataclass
class FilterStage:
    """Filter rows (WHERE or HAVING)."""
    predicate: Any


@dataclass
class GroupByStage:
    """Form groups."""
    keys: list[Any] = field(default_factory=list)


@dataclass
class SelectStage:
    """Project columns (SELECT)."""
    items: list[Any] = field(default_factory=list)


@dataclass
class DistinctStage:
    """Remove duplicate rows."""
    pass


@dataclass
class SortStage:
    """Sort rows."""
    keys: list[Any] = field(default_factory=list)  # list of (expr, ascending)


@dataclass
class OffsetStage:
    """Skip N rows."""
    n: int


@dataclass
class LimitStage:
    """Keep at most N rows."""
    n: int
    pass


Plan = list[Any]


def plan(query: Query) -> Plan:
    """Convert a Query into an ordered list of plan stages."""
    stages: Plan = []

    # 1. FROM
    stages.append(ScanStage(table=query.from_table))

    # 2. JOIN
    if query.join is not None:
        stages.append(
            JoinStage(
                join_type=query.join.type,
                table=query.join.table,
                on=query.join.on,
            )
        )

    # 3. WHERE
    if query.where is not None:
        stages.append(FilterStage(predicate=query.where))

    # 4. GROUP BY
    if query.group_by:
        stages.append(GroupByStage(keys=query.group_by))

    # 5. HAVING
    if query.having is not None:
        stages.append(FilterStage(predicate=query.having))

    # 6. SELECT
    stages.append(SelectStage(items=query.select_items))

    # 7. DISTINCT
    if query.distinct:
        stages.append(DistinctStage())

    # 8. ORDER BY
    if query.order_by:
        stages.append(
            SortStage(
                keys=[(ob.expr, ob.ascending) for ob in query.order_by]
            )
        )

    # 9. OFFSET
    if query.offset is not None:
        stages.append(OffsetStage(n=query.offset))

    # 10. LIMIT
    if query.limit is not None:
        stages.append(LimitStage(n=query.limit))

    return stages

"""Query executor: runs a Plan against tables and produces a Result."""

import dataclasses
from typing import Any

from microdb.errors import (
    TypeMismatchError,
    AggregateError,
    GroupingError,
    UnknownColumnError,
    MicroDBError,
)
from microdb.schema import Table
from microdb.expr import (
    EvalContext,
    evaluate,
    contains_aggregate,
    collect_aggregates,
)
from microdb.aggregate import eval_aggregate
from microdb.planner import (
    ScanStage,
    JoinStage,
    FilterStage,
    GroupByStage,
    SelectStage,
    DistinctStage,
    SortStage,
    OffsetStage,
    LimitStage,
)
from microdb.parser import (
    SelectExpr,
    Star,
    StarTable,
    ColumnRef,
    FunctionCall,
    BinaryOp,
    UnaryOp,
    IsNull,
    Literal,
    QualifiedColumnRef,
)
from microdb.value import compare_lt, type_of


@dataclasses.dataclass(frozen=True)
class Result:
    """Query execution result."""
    columns: list[str]
    rows: list[list[object]]


def execute_plan(plan: list[Any], tables: dict[str, Table]) -> Result:
    """Execute a plan against the given tables."""
    # State
    rows: list[list[object]] = []
    col_names: list[str] = []
    table_col_map: dict[str, dict[str, int]] = {}
    # True if we are in group mode (after GROUP BY)
    group_mode = False
    group_key_exprs: list[Any] = []
    groups: list[tuple[list[object], list[list[object]]]] = []

    for stage in plan:
        if isinstance(stage, ScanStage):
            rows, col_names, table_col_map = _exec_scan(
                stage, tables
            )

        elif isinstance(stage, JoinStage):
            rows, col_names, table_col_map = _exec_join(
                stage, rows, col_names, table_col_map, tables
            )

        elif isinstance(stage, FilterStage):
            if group_mode and groups:
                # HAVING
                groups = _exec_having(
                    stage, groups, col_names, table_col_map, tables
                )
            else:
                # WHERE
                rows = _exec_where(
                    stage, rows, col_names, table_col_map, tables
                )

        elif isinstance(stage, GroupByStage):
            group_key_exprs = stage.keys
            groups = _exec_group_by(
                stage, rows, col_names, table_col_map, tables
            )
            group_mode = True
            rows = []

        elif isinstance(stage, SelectStage):
            if group_mode and groups:
                rows, col_names, table_col_map = _exec_select_grouped(
                    stage, groups, group_key_exprs,
                    col_names, table_col_map, tables,
                )
            elif contains_aggregate_in_items(stage.items):
                # No GROUP BY, but aggregates present: whole input is one group
                groups = [
                    (_make_group_key(None, rows), list(rows))
                ]
                rows, col_names, table_col_map = _exec_select_grouped(
                    stage, groups, [],
                    col_names, table_col_map, tables,
                )
            else:
                rows, col_names, table_col_map = _exec_select_per_row(
                    stage, rows, col_names, table_col_map, tables
                )

        elif isinstance(stage, DistinctStage):
            rows = _exec_distinct(rows)

        elif isinstance(stage, SortStage):
            rows = _exec_sort(
                stage, rows, col_names, table_col_map, tables
            )

        elif isinstance(stage, OffsetStage):
            rows = rows[stage.n:]

        elif isinstance(stage, LimitStage):
            rows = rows[:stage.n]

    return Result(columns=col_names, rows=rows)


# ── Scan ───────────────────────────────────────────────────────────────

def _exec_scan(
    stage: ScanStage, tables: dict[str, Table]
) -> tuple[list[list[object]], list[str], dict[str, dict[str, int]]]:
    table = tables[stage.table]
    rows = [list(r) for r in table.rows]
    col_names = [c.name for c in table.columns]
    table_col_map = {
        stage.table: {c.name: i for i, c in enumerate(table.columns)}
    }
    return rows, col_names, table_col_map


# ── Join ───────────────────────────────────────────────────────────────

def _exec_join(
    stage: JoinStage,
    left_rows: list[list[object]],
    left_col_names: list[str],
    left_table_col_map: dict[str, dict[str, int]],
    tables: dict[str, Table],
) -> tuple[list[list[object]], list[str], dict[str, dict[str, int]]]:
    right_table = tables[stage.table]
    right_rows = [list(r) for r in right_table.rows]
    right_col_names = [c.name for c in right_table.columns]
    right_col_map = {c.name: i for i, c in enumerate(right_table.columns)}

    # Build combined column names
    combined_names = left_col_names + right_col_names

    # Build table_col_map
    combined_tcm: dict[str, dict[str, int]] = {}
    for tbl, cmap in left_table_col_map.items():
        combined_tcm[tbl] = dict(cmap)
    combined_tcm[stage.table] = {
        c: i + len(left_col_names)
        for c, i in right_col_map.items()
    }

    # Build EvalContext for ON clause
    base_col_names = combined_names
    base_tcm = combined_tcm
    ctx = EvalContext(
        col_names=base_col_names,
        table_col_map=base_tcm,
        tables=tables,
    )

    result_rows: list[list[object]] = []
    left_matched: set[int] = set()

    for li, lrow in enumerate(left_rows):
        for ri, rrow in enumerate(right_rows):
            combined = list(lrow) + list(rrow)
            ctx_row = ctx.with_row(combined)
            val = evaluate(stage.on, ctx_row)
            if val is True:
                result_rows.append(combined)
                left_matched.add(li)

        if stage.join_type == "LEFT" and li not in left_matched:
            null_right = [None] * len(right_col_names)
            combined = list(lrow) + null_right
            result_rows.append(combined)

    return result_rows, base_col_names, base_tcm


# ── WHERE ──────────────────────────────────────────────────────────────

def _exec_where(
    stage: FilterStage,
    rows: list[list[object]],
    col_names: list[str],
    table_col_map: dict[str, dict[str, int]],
    tables: dict[str, Table],
) -> list[list[object]]:
    # Verify no aggregates in WHERE
    if contains_aggregate(stage.predicate):
        raise AggregateError("WHERE cannot contain aggregate")

    ctx = EvalContext(
        col_names=col_names,
        table_col_map=table_col_map,
        tables=tables,
    )

    result: list[list[object]] = []
    for row in rows:
        ctx_row = ctx.with_row(row)
        val = evaluate(stage.predicate, ctx_row)
        if val is True:
            result.append(row)

    return result


# ── GROUP BY ───────────────────────────────────────────────────────────

def _exec_group_by(
    stage: GroupByStage,
    rows: list[list[object]],
    col_names: list[str],
    table_col_map: dict[str, dict[str, int]],
    tables: dict[str, Table],
) -> list[tuple[list[object], list[list[object]]]]:
    """Form groups from rows. Returns list of (key_row, group_rows)."""
    ctx = EvalContext(
        col_names=col_names,
        table_col_map=table_col_map,
        tables=tables,
    )

    groups: list[tuple[list[object], list[list[object]]]] = []
    key_map: dict[tuple, int] = {}

    for row in rows:
        ctx_row = ctx.with_row(row)
        key_vals: list[object] = []
        for ke in stage.keys:
            v = evaluate(ke, ctx_row)
            key_vals.append(v)

        # NULL = NULL for grouping purposes
        key_tuple = _null_key_tuple(key_vals)

        if key_tuple in key_map:
            gi = key_map[key_tuple]
            groups[gi][1].append(row)
        else:
            gi = len(groups)
            key_map[key_tuple] = gi
            groups.append((key_vals, [row]))

    return groups


def _null_key_tuple(key_vals: list[object]) -> tuple:
    """Convert key values to a hashable tuple, treating NULL as equal."""
    return tuple(_null_sentinel(v) for v in key_vals)


def _null_sentinel(v: object) -> object:
    """Return a sentinel that makes None group together."""
    if v is None:
        return _NULL_SENTINEL
    return v


_NULL_SENTINEL = object()


def _make_group_key(
    key_exprs: list[Any] | None, rows: list[list[object]]
) -> list[object]:
    """Build a synthetic group key for the no-GROUP-BY with aggregates case."""
    return []


# ── HAVING ─────────────────────────────────────────────────────────────

def _exec_having(
    stage: FilterStage,
    groups: list[tuple[list[object], list[list[object]]]],
    col_names: list[str],
    table_col_map: dict[str, dict[str, int]],
    tables: dict[str, Table],
) -> list[tuple[list[object], list[list[object]]]]:
    ctx = EvalContext(
        col_names=col_names,
        table_col_map=table_col_map,
        tables=tables,
    )

    result: list[tuple[list[object], list[list[object]]]] = []
    for key_vals, group_rows in groups:
        val = _eval_group_predicate(
            stage.predicate, group_rows, ctx
        )
        if val is True:
            result.append((key_vals, group_rows))

    return result


def _eval_group_predicate(
    expr: object, group_rows: list[list[object]], ctx: EvalContext
) -> object:
    """Evaluate an expression over a group, handling aggregates."""
    if isinstance(expr, FunctionCall) and expr.name.upper() in (
        "COUNT", "SUM", "AVG", "MIN", "MAX"
    ):
        return eval_aggregate(
            expr, group_rows,
            lambda e, r: evaluate(e, ctx.with_row(r)),
        )

    if isinstance(expr, BinaryOp):
        if expr.op == "AND":
            lv = _eval_group_predicate(expr.left, group_rows, ctx)
            if lv is False:
                return False
            rv = _eval_group_predicate(expr.right, group_rows, ctx)
            if lv is None or rv is None:
                return None if lv is not False and rv is not False else False
            return lv and rv
        if expr.op == "OR":
            lv = _eval_group_predicate(expr.left, group_rows, ctx)
            if lv is True:
                return True
            rv = _eval_group_predicate(expr.right, group_rows, ctx)
            if lv is None or rv is None:
                return None if lv is not True and rv is not True else True
            return lv or rv
        lv = _eval_group_predicate(expr.left, group_rows, ctx)
        rv = _eval_group_predicate(expr.right, group_rows, ctx)
        if expr.op in ("=", "<>", "<", "<=", ">", ">="):
            from microdb.expr import _compare
            return _compare(expr.op, lv, rv)
        from microdb.value import arith
        return arith(expr.op, lv, rv)

    if isinstance(expr, UnaryOp):
        val = _eval_group_predicate(expr.operand, group_rows, ctx)
        if expr.op == "NOT":
            from microdb.value import not_
            return not_(val)
        from microdb.value import negate
        return negate(val)

    if isinstance(expr, IsNull):
        val = _eval_group_predicate(expr.operand, group_rows, ctx)
        if expr.negated:
            return val is not None
        return val is None

    # Non-aggregate expression: evaluate against first row
    if group_rows:
        return evaluate(expr, ctx.with_row(group_rows[0]))
    return None


# ── SELECT (grouped) ───────────────────────────────────────────────────

def _exec_select_grouped(
    stage: SelectStage,
    groups: list[tuple[list[object], list[list[object]]]],
    group_key_exprs: list[Any],
    input_col_names: list[str],
    table_col_map: dict[str, dict[str, int]],
    tables: dict[str, Table],
) -> tuple[list[list[object]], list[str], dict[str, dict[str, int]]]:
    """Evaluate SELECT over groups."""
    ctx = EvalContext(
        col_names=input_col_names,
        table_col_map=table_col_map,
        tables=tables,
    )

    result_rows: list[list[object]] = []
    out_col_names: list[str] = []

    for si_idx, item in enumerate(stage.items):
        out_col_names.append(_get_output_col_name(item, si_idx))

    for _key_vals, group_rows in groups:
        out_row: list[object] = []
        for item in stage.items:
            if isinstance(item, Star):
                # Expand to all input columns
                for cn in input_col_names:
                    out_row.append(
                        evaluate(
                            ColumnRef(cn),
                            ctx.with_row(
                                group_rows[0] if group_rows else []
                            ),
                        )
                    )
                continue

            if isinstance(item, StarTable):
                # Expand to all columns from that table
                tbl = item.table
                if tbl in table_col_map:
                    for cn in table_col_map[tbl]:
                        out_row.append(
                            evaluate(
                                QualifiedColumnRef(tbl, cn),
                                ctx.with_row(
                                    group_rows[0] if group_rows else []
                                ),
                            )
                        )
                continue

            expr = item.expr
            # Determine if this expression contains aggregates
            if _has_agg(expr):
                val = _eval_group_expression(
                    expr, group_rows, ctx
                )
                out_row.append(val)
            else:
                # Non-aggregate: evaluate against first row of group
                if group_rows:
                    out_row.append(
                        evaluate(expr, ctx.with_row(group_rows[0]))
                    )
                else:
                    out_row.append(None)

        result_rows.append(out_row)

    return result_rows, out_col_names, {}


def _has_agg(expr: object) -> bool:
    """Check if an expression contains aggregate functions."""
    if isinstance(expr, FunctionCall):
        if expr.name.upper() in ("COUNT", "SUM", "AVG", "MIN", "MAX"):
            return True
        return any(_has_agg(a) for a in expr.args)
    if isinstance(expr, BinaryOp):
        return _has_agg(expr.left) or _has_agg(expr.right)
    if isinstance(expr, UnaryOp):
        return _has_agg(expr.operand)
    if isinstance(expr, IsNull):
        return _has_agg(expr.operand)
    return False


def _eval_group_expression(
    expr: object,
    group_rows: list[list[object]],
    ctx: EvalContext,
) -> object:
    """Evaluate an expression that may contain aggregates over a group."""
    if isinstance(expr, FunctionCall) and expr.name.upper() in (
        "COUNT", "SUM", "AVG", "MIN", "MAX"
    ):
        return eval_aggregate(
            expr, group_rows,
            lambda e, r: evaluate(e, ctx.with_row(r)),
        )

    if isinstance(expr, FunctionCall):
        # Scalar function: evaluate args (which may contain aggregates)
        evaled_args = [
            _eval_group_expression(a, group_rows, ctx)
            for a in expr.args
        ]
        from microdb.expr import _eval_function
        fc = FunctionCall(expr.name, evaled_args)
        return _eval_function(fc, ctx)

    if isinstance(expr, BinaryOp):
        lv = _eval_group_expression(expr.left, group_rows, ctx)
        rv = _eval_group_expression(expr.right, group_rows, ctx)
        from microdb.value import arith, compare_eq, compare_lt
        from microdb.expr import and_, or_, not_
        if expr.op == "AND":
            return and_(lv, rv)
        if expr.op == "OR":
            return or_(lv, rv)
        if expr.op in ("=", "<>", "<", "<=", ">", ">="):
            from microdb.expr import _compare
            return _compare(expr.op, lv, rv)
        return arith(expr.op, lv, rv)

    if isinstance(expr, UnaryOp):
        val = _eval_group_expression(expr.operand, group_rows, ctx)
        if expr.op == "NOT":
            from microdb.value import not_
            return not_(val)
        from microdb.value import negate
        return negate(val)

    if isinstance(expr, IsNull):
        val = _eval_group_expression(expr.operand, group_rows, ctx)
        if expr.negated:
            return val is not None
        return val is None

    # Non-aggregate leaf: evaluate against first row
    if group_rows:
        return evaluate(expr, ctx.with_row(group_rows[0]))
    return None


# ── SELECT (per row, no aggregates) ────────────────────────────────────

def _exec_select_per_row(
    stage: SelectStage,
    rows: list[list[object]],
    col_names: list[str],
    table_col_map: dict[str, dict[str, int]],
    tables: dict[str, Table],
) -> tuple[list[list[object]], list[str], dict[str, dict[str, int]]]:
    """Evaluate SELECT over individual rows (no GROUP BY, no aggregates)."""
    ctx = EvalContext(
        col_names=col_names,
        table_col_map=table_col_map,
        tables=tables,
    )

    out_col_names: list[str] = []
    for si_idx, item in enumerate(stage.items):
        out_col_names.append(_get_output_col_name(item, si_idx))

    result_rows: list[list[object]] = []
    for row in rows:
        ctx_row = ctx.with_row(row)
        out_row: list[object] = []
        for item in stage.items:
            if isinstance(item, Star):
                for cn in col_names:
                    out_row.append(evaluate(ColumnRef(cn), ctx_row))
                continue
            if isinstance(item, StarTable):
                tbl = item.table
                if tbl in table_col_map:
                    for cn in table_col_map[tbl]:
                        out_row.append(
                            evaluate(QualifiedColumnRef(tbl, cn), ctx_row)
                        )
                continue
            out_row.append(evaluate(item.expr, ctx_row))
        result_rows.append(out_row)

    return result_rows, out_col_names, {}


def _get_output_col_name(item: Any, idx: int) -> str:
    """Determine the output column name for a SELECT item."""
    if isinstance(item, Star):
        return "*"
    if isinstance(item, StarTable):
        return f"{item.table}.*"
    if item.alias:
        return item.alias
    return _expr_to_str(item.expr)


def _expr_to_str(expr: object) -> str:
    """Convert an expression to a string with collapsed whitespace."""
    parts: list[str] = []

    if isinstance(expr, Literal):
        v = expr.value
        if v is None:
            return "NULL"
        if isinstance(v, bool):
            return "TRUE" if v else "FALSE"
        if isinstance(v, str):
            return f"'{v}'"
        return str(v)

    if isinstance(expr, ColumnRef):
        return expr.name

    if isinstance(expr, QualifiedColumnRef):
        return f"{expr.table}.{expr.name}"

    if isinstance(expr, FunctionCall):
        args = ", ".join(_expr_to_str(a) for a in expr.args)
        return f"{expr.name}({args})"

    if isinstance(expr, Star):
        return "*"

    if isinstance(expr, BinaryOp):
        left = _expr_to_str(expr.left)
        right = _expr_to_str(expr.right)
        return f"{left} {expr.op} {right}"

    if isinstance(expr, UnaryOp):
        if expr.op == "NOT":
            return f"NOT {_expr_to_str(expr.operand)}"
        return f"-{_expr_to_str(expr.operand)}"

    if isinstance(expr, IsNull):
        base = _expr_to_str(expr.operand)
        if expr.negated:
            return f"{base} IS NOT NULL"
        return f"{base} IS NULL"

    return str(expr)


# ── DISTINCT ───────────────────────────────────────────────────────────

def _exec_distinct(
    rows: list[list[object]],
) -> list[list[object]]:
    seen: set[tuple] = set()
    result: list[list[object]] = []
    for row in rows:
        key = tuple(_null_sentinel(v) for v in row)
        if key not in seen:
            seen.add(key)
            result.append(row)
    return result


# ── SORT ───────────────────────────────────────────────────────────────

def _exec_sort(
    stage: SortStage,
    rows: list[list[object]],
    col_names: list[str],
    table_col_map: dict[str, dict[str, int]],
    tables: dict[str, Table],
) -> list[list[object]]:
    if not rows:
        return rows

    # Build a row-index list and sort it stably
    indices = list(range(len(rows)))
    ctx = EvalContext(
        col_names=col_names,
        table_col_map=table_col_map,
        tables=tables,
    )

    def _sort_key(idx: int) -> tuple:
        row = rows[idx]
        ctx_row = ctx.with_row(row)
        key_vals: list[object] = []
        for expr, _asc in stage.keys:
            v = evaluate(expr, ctx_row)
            key_vals.append(v)
        return _make_sort_tuple(key_vals, stage.keys)

    indices.sort(key=_sort_key)
    # Stable sort: Python's sort is stable by default

    return [rows[i] for i in indices]


def _make_sort_tuple(
    values: list[object], keys: list[tuple[Any, bool]]
) -> tuple:
    """Create a sort key tuple from values.

    NULL sorts after every non-NULL value.
    """
    result: list[object] = []
    for i, (v, _asc) in enumerate(zip(values, keys)):
        if v is None:
            # None sorts last: use (1,) for NULL, (0, sentinel) for non-NULL
            result.append((1,))
        else:
            result.append((0, v))
    return tuple(result)


def contains_aggregate_in_items(items: list[Any]) -> bool:
    """Check if any SELECT item contains an aggregate."""
    for item in items:
        if isinstance(item, (Star, StarTable)):
            continue
        if _has_agg(item.expr):
            return True
    return False

